svg.script:
const target=new URL("/gh/unblockedgames99x-code/gsn-console-cdn@v20260929-1/"+'console.svg',location.origin).href;
const host=document.getElementById('launcher'), message=document.getElementById('message'),back=document.getElementById('back');
const permissions='autoplay; fullscreen; gamepad; encrypted-media; picture-in-picture; clipboard-write; microphone; camera';
function launchHere(){if(document.getElementById('game'))return;const frame=document.createElementNS('http://www.w3.org/1999/xhtml','iframe');frame.id='game';frame.title='GSN console';frame.src=target;frame.setAttribute('allow',permissions);frame.setAttribute('allowfullscreen','true');host.appendChild(frame);back.hidden=false;}
document.getElementById('normal').onclick=launchHere;
document.getElementById('fullscreen').onclick=()=>{const request=host.requestFullscreen?.();launchHere();if(request)request.catch(()=>{back.textContent='Launcher · fullscreen unavailable';});};
back.onclick=()=>{document.getElementById('game')?.remove();back.hidden=true;back.textContent='Launcher';if(document.fullscreenElement)document.exitFullscreen().catch(()=>{});};
document.getElementById('blank').onclick=()=>{
 const child=window.open('about:blank','_blank');if(!child){message.textContent='Allow pop-ups for this site, then try again.';return;}
 const doc=child.document;doc.title='GSN · Console';doc.documentElement.style.cssText='height:100%;background:#080f1d';doc.body.style.cssText='margin:0;height:100%;background:#080f1d;color:#eaf1ff;font:14px system-ui';
 const bar=doc.createElement('div');bar.style.cssText='height:48px;display:flex;align-items:center;justify-content:space-between;padding:0 18px;box-sizing:border-box;background:linear-gradient(110deg,#101d30,#193557)';
 const name=doc.createElement('strong');name.textContent='GSN';name.style.letterSpacing='.22em';bar.appendChild(name);
 const button=doc.createElement('button');button.textContent='Fullscreen';button.style.cssText='font:inherit;border:1px solid #c5dcff55;border-radius:18px;padding:6px 18px;background:#eaf3ff;color:#102139;cursor:pointer';bar.appendChild(button);doc.body.appendChild(bar);
 const frame=doc.createElement('iframe');frame.title='GSN console';frame.src=target;frame.allow=permissions;frame.allowFullscreen=true;frame.style.cssText='display:block;width:100%;height:calc(100% - 48px);border:0;background:#080b14';doc.body.appendChild(frame);
 button.onclick=()=>{const request=doc.fullscreenElement?doc.exitFullscreen():doc.documentElement.requestFullscreen();request.catch(()=>{button.textContent='Fullscreen unavailable';});};
 doc.onfullscreenchange=()=>{button.textContent=doc.fullscreenElement?'Exit fullscreen':'Fullscreen';};
 child.opener=null;message.textContent='Your console opened in a new tab.';
};
